void IDS()
{
    Open = {T₀}, ds = k;
    while Open ≠ ∅ do
    {
        n ← get (Open)
        if (n = T_G) then return True
        Closed = Closed ∪ {n}
        case d(n) do
        {
            0 .. ds - 1: Đặt A(n) vào đầu Open
            ds: Đặt A(n) vào cuối Open
            ds + 1:
            {
                ds = ds + k   // tăng độ sâu
                if k = 1 then đặt A(n) vào cuối tập Open
                else đặt A(n) vào đầu tập Open
            }
        }
    }
    return False
}
